{

"kind": "propose",
"summary": "The 'api' container in the 'search' Deployment is consistently hitting its CPU limit, causing throttling and readiness probe failures. Increasing the CPU limit to 750m should alleviate the throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The container's CPU usage is near its limit, and it's being throttled, leading to performance issues.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "The increased CPU limit should reduce throttling, allowing the container to meet its CPU demands and prevent readiness probe timeouts.",
  "rationale": "The container is consistently hitting its CPU limit (0.5 CPU) with usage at 0.498 CPU, leading to 58% throttling. This is causing readiness probe failures. Raising the limit to 750m (1.5x current) should clear the throttling without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
